import {MarkdownRenderer} from '@github-ui/copilot-markdown'
import {clsx} from 'clsx'
import {useEffect, useState} from 'react'

import {Typewriter} from '../../shared/Typewriter'
import styles from './Summary.module.css'

interface SummaryProps {
  title?: string
  content: string | string[]
  className?: string
  onAnimationStart?: () => void
  onAnimationComplete?: () => void
  onContentVisible?: () => void
  isLoading?: boolean
  loadingText?: string
  shouldAnimate?: boolean // Control whether animation occurs
}

export const Summary = ({
  title,
  content,
  className,
  onAnimationStart,
  onAnimationComplete,
  onContentVisible,
  isLoading = false,
  loadingText = 'Loading...',
  shouldAnimate = true, // Default to true for backward compatibility
}: SummaryProps) => {
  const isStringContent = typeof content === 'string'
  const [isAnimating, setIsAnimating] = useState(true)
  const [animationKey, setAnimationKey] = useState(0)
  const [currentItemIndex, setCurrentItemIndex] = useState(0)

  // Animate both string and array content, but only if content exists AND shouldAnimate is true
  const hasContent = isStringContent ? content.trim().length > 0 : content.length > 0
  const shouldUseAnimation = hasContent && shouldAnimate

  // Trigger animation when content changes
  useEffect(() => {
    if (hasContent) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setIsAnimating(true)
      setAnimationKey(prev => prev + 1)
      setCurrentItemIndex(0)
      onAnimationStart?.()
    }
  }, [content, onAnimationStart, hasContent])

  const handleAnimationComplete = () => {
    if (!isStringContent && currentItemIndex < content.length - 1) {
      // Move to next list item
      setCurrentItemIndex(prev => prev + 1)
    } else {
      // All done - either string content finished or all list items finished
      setIsAnimating(false)
      onAnimationComplete?.()
      onContentVisible?.()
    }
  }

  // For non-animated content, call onContentVisible immediately
  useEffect(() => {
    if (!shouldUseAnimation && hasContent) {
      onContentVisible?.()
    }
  }, [shouldUseAnimation, onContentVisible, hasContent])

  // If we're loading and have no content, show loading placeholder
  if (isLoading && !hasContent) {
    return (
      <div className={clsx(styles.summaryContainer, className)}>
        <Typewriter text={loadingText} speed={50} showDots className={styles.typewriterText} />
      </div>
    )
  }

  // Don't render anything if no content and not loading
  if (!hasContent) {
    return null
  }

  return (
    <div className={clsx(styles.summaryContainer, className)}>
      {title && <h3 className={styles.summaryTitle}>{title}</h3>}
      <div>
        {shouldUseAnimation && isAnimating ? (
          <div key={animationKey} className={styles.typewriterContainer}>
            {isStringContent ? (
              // String content: animate as-is
              <Typewriter
                text={content}
                speed={20}
                onComplete={handleAnimationComplete}
                className={styles.typewriterText}
                showDots={false}
              />
            ) : (
              // Array content: render as HTML list and animate each item progressively
              <ul className={styles.summaryList}>
                {content.slice(0, currentItemIndex + 1).map((point, index) => (
                  <li
                    key={`${animationKey}-item-${point.replace(/\W/g, '').slice(0, 30)}`}
                    className={styles.summaryListItem}
                  >
                    {index === currentItemIndex ? (
                      // Animate the current item
                      <Typewriter
                        text={point}
                        speed={20}
                        onComplete={handleAnimationComplete}
                        className={styles.typewriterText}
                        showDots={false}
                      />
                    ) : (
                      // Show completed items as static text
                      point
                    )}
                  </li>
                ))}
              </ul>
            )}
          </div>
        ) : (
          // Show final formatted content
          <>
            {isStringContent ? (
              <MarkdownRenderer markdown={content} chatMode="assistive" className={styles.markdownContent} />
            ) : (
              <ul className={styles.summaryList}>
                {content.map(point => (
                  <li key={`summary-item-${point.slice(0, 50).replace(/\s/g, '')}`} className={styles.summaryListItem}>
                    {point}
                  </li>
                ))}
              </ul>
            )}
          </>
        )}
      </div>
    </div>
  )
}

try{ Summary.displayName ||= 'Summary' } catch {}