import {clsx} from 'clsx'
import {type ReactNode, useEffect, useState} from 'react'

import styles from './Typewriter.module.css'

interface TypewriterProps {
  text: string
  speed?: number
  onComplete?: () => void
  className?: string
  showDots?: boolean
}

export const Typewriter = ({text, speed = 50, onComplete, className, showDots = true}: TypewriterProps) => {
  const [displayed, setDisplayed] = useState('')
  const [isComplete, setIsComplete] = useState(false)

  useEffect(() => {
    let idx = 0
    setDisplayed('')
    setIsComplete(false)

    const interval = setInterval(() => {
      setDisplayed(text.slice(0, ++idx))
      if (idx === text.length) {
        clearInterval(interval)
        setIsComplete(true)
        onComplete?.()
      }
    }, speed)

    return () => clearInterval(interval)
  }, [text, speed, onComplete])

  return (
    <>
      <span className="sr-only" aria-live="polite">
        {isComplete ? text : ''}
      </span>

      <span className={clsx(className || 'text-small fgColor-muted')} aria-hidden="true">
        {displayed}
        {isComplete && showDots && <span className={styles.dots} />}
      </span>
    </>
  )
}

interface WithShimmerEffectProps {
  children: ReactNode
  className?: string
}

export const WithShimmerEffect = ({children, className}: WithShimmerEffectProps) => {
  return <div className={clsx(styles.shimmerText, className)}>{children}</div>
}

try{ Typewriter.displayName ||= 'Typewriter' } catch {}
try{ WithShimmerEffect.displayName ||= 'WithShimmerEffect' } catch {}