type AttachableError = SparkError & {attached: boolean; dismissed?: boolean}
const getAttachments = (errors: AttachableError[]) => ({errors: errors.map(e => ({message: e.messageRaw}))})

interface IteratePanelProps {
  workbenchData: UseWorkbenchReturn
}
const IteratePanel = ({workbenchData}: IteratePanelProps) => {
  const {cancelPrompt, isFetching, submitPrompt, suggestions, setIsMobileSidebarOpen} = workbenchData
  const {
    promptText: globalPromptText,
    setPromptText: setGlobalPromptText,
    pendingSubmission,
    promptError,
    setPromptError,
    promptImage,
    attachImage,
    clearImageAttachment,
    imageUploadError,
    setImageUploadError,
  } = useUserPromptContext()
  const {previousRefinements, currentRefinementSha, refreshGitHistory, setIsNavigatingHistory, gitHistoryRestored} =
    useIterationHistory()

  const {updateWorkbenchCurrentRefinement} = useWorkbench()
  const {codespaceData} = useCodespaceContext()
  const {friendlyName} = codespaceData.codespaceInfo?.environment_data || {}
  const domain = codespaceData.remoteProvider?.tunnelProps.domain ?? 'app.github.dev'
  const tunnelToken =
    codespaceData.codespaceInfo?.environment_data.connection.tunnelProperties?.connectAccessToken || ''
  const isCodespaceReady = friendlyName && domain && tunnelToken && codespaceData.codespaceState === 'ready'

  const shouldForcePushToRemoteAfterCheckout = isFeatureEnabled('spark_force_push_after_checkout')

  const {iterateErrors, deployBuildErrors, setDeployBuildErrors} = useErrors()
  const [errors, setErrors] = useState<AttachableError[]>([])
  const attachedErrors = errors.filter(er => er.attached)

  const promptInputRef = useRef<HTMLTextAreaElement>(null)
  const imageUploadErrorRef = useRef<HTMLDivElement>(null)
  const imagesInputRef = useRef<HTMLInputElement>(null)
  const attachImageButtonRef = useRef<HTMLButtonElement>(null)
  const scrollRef = useRef<HTMLDivElement>(null)
  const sendEvent = useAnalytics()
  const {fileSyncerStarted, syncerMode, getFileSyncerV2, forceContentRefresh, forceFileTreeRefresh} =
    useFileSyncerContext()

  const readOnly = useReadOnly(ReadOnlyKey.GENERATE_ACTIONS)
  const workbenchStore = useWorkbenchStore()
  const step = previousRefinements.length ? 'refine' : 'generate'

  const updatePromptText = useCallback(
    (newValue: string) => {
      const el = promptInputRef.current
      if (!el) return
      el.value = newValue ?? pendingSubmission?.promptText ?? ''
      el.style.height = 'auto'
      el.style.height = `${el.scrollHeight}px`
    },
    [promptInputRef, pendingSubmission?.promptText],
  )

  useEffect(() => {
    updatePromptText(globalPromptText)
  }, [globalPromptText, updatePromptText])

  const activeRefinement = useMemo(() => {
    return previousRefinements.find(r => r.sha === currentRefinementSha)
  }, [currentRefinementSha, previousRefinements])

  // when user lands we want to scroll to the active iteration
  useLayoutEffect(() => {
    // see https://github.com/github/github/pull/395713#discussion_r2276764630 for why setTimeout is currently necessary :/
    const timeoutId = setTimeout(() => {
      const element = document.querySelector(`[data-timeline-refinement-active="true"]`)

      if (element) {
        element.scrollIntoView({block: 'start', behavior: 'smooth'})
      }
    }, 100)

    return () => {
      clearTimeout(timeoutId)
    }
  }, [])

  // when the user adds a new item, automatically scroll to the bottom if the container can scroll.
  // we want to only run when the length really changed, not for initial render
  const prevRefinementsLength = useRef(previousRefinements.length)
  useEffect(() => {
    if (previousRefinements.length === prevRefinementsLength.current) return

    scrollRef.current?.scrollTo({
      top: scrollRef.current.scrollHeight,
      behavior: 'smooth',
    })

    prevRefinementsLength.current = previousRefinements.length
  }, [previousRefinements])

  const [selectedRefinement, setSelectedRefinement] = useState(activeRefinement)

  useEffect(() => {
    setErrors(prevErrors => {
      const existing = new Map(prevErrors.map(e => [e.messageRaw, {attached: e.attached, dismissed: e.dismissed}]))
      return iterateErrors.map(e => ({
        source: e.source,
        messageRaw: e.messageRaw,
        messagePretty: e.messagePretty,
        path: e.path,
        line: e.line,
        column: e.column,
        location: e.location,
        attached: existing.get(e.messageRaw)?.attached ?? false,
        dismissed: existing.get(e.messageRaw)?.dismissed ?? false,
      }))
    })
  }, [iterateErrors])

  useEffect(() => {
    // Focus the image upload error banner when it appears
    if (imageUploadError) {
      imageUploadErrorRef.current?.focus()
    }
  }, [imageUploadError])

  const attachAll = useCallback((attached: boolean) => {
    setErrors(prev => {
      const updated = prev.map(e => ({...e, attached}))
      return updated
    })
  }, [])

  const handleSubmit = useStableCallback(
    async (prompt: string, method: string, additionalTelemetryProperties?: Record<string, unknown>) => {
      if (!isCodespaceReady) return

      const currentDeployBuildErrors = deployBuildErrors

      workbenchStore.reloadQuota()

      updatePromptText('')
      setDeployBuildErrors([])
      setIsMobileSidebarOpen(false)
      setPromptError(null)

      let result: {success: boolean; error?: Error | null} | undefined = undefined

      const attachments = getAttachments(attachedErrors)
      result = await submitPrompt(prompt, step, method, {attachments, additionalTelemetryProperties})
      if (attachments.errors.length !== 0) {
        attachAll(false)
      }

      // reset values back on error
      if (!result?.success) {
        updatePromptText(prompt)
        setDeployBuildErrors(currentDeployBuildErrors)
        setPromptError(result?.error?.message ?? 'Failed to process prompt.')
      }
    },
  )

  const handleIterationNavigation = useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if (!isFeatureEnabled('workbench_iteration_keyboard_navigation')) return

      const aiRefinements = previousRefinements.filter(r => r.iteration_type === 'ai')

      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
      const [arrowUp, arrowDown] = [e.key === 'ArrowUp', e.key === 'ArrowDown']

      if (!promptInputRef.current || (!arrowUp && !arrowDown)) return

      // if the user navigates inside composition dialog (e.g., using an IME), ignore
      if (e.nativeEvent.isComposing) {
        return
      }

      const start = promptInputRef.current.selectionStart
      const end = promptInputRef.current.selectionEnd
      const noSelection = start === end
      const length = promptInputRef.current.textLength

      if (noSelection && start === 0 && arrowUp) {
        e.preventDefault()
        if (!selectedRefinement) {
          setSelectedRefinement(aiRefinements.at(-1))
          updatePromptText(aiRefinements.at(-1)?.prompt ?? '')
          promptInputRef.current.setSelectionRange(0, 0)
        } else {
          const previousRefinement = aiRefinements.find(r => r.id === selectedRefinement.parentId)
          if (!previousRefinement?.prompt) return
          setSelectedRefinement(previousRefinement)
          updatePromptText(previousRefinement.prompt)
          promptInputRef.current.setSelectionRange(0, 0)
        }
      }
      if (noSelection && start === length && arrowDown && selectedRefinement) {
        e.preventDefault()
        const nextRefinement = aiRefinements.find(r => r.parentId === selectedRefinement.id)
        if (!nextRefinement?.prompt) {
          setSelectedRefinement(undefined)
          updatePromptText('')
        } else {
          setSelectedRefinement(nextRefinement)
          updatePromptText(nextRefinement.prompt ?? '')
          promptInputRef.current.setSelectionRange(nextRefinement.prompt.length, nextRefinement.prompt.length)
        }
      }
    },
    [previousRefinements, selectedRefinement, updatePromptText],
  )

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      handleIterationNavigation(e)

      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
      const isEnter = e.key === 'Enter'

      if (!isEnter || e.shiftKey || isMobile()) return

      // if the user is composing text (e.g., using an IME), do not submit yet
      if (isEnter && e.nativeEvent.isComposing) {
        return
      }

      e.preventDefault()
      handleSubmit(promptInputRef.current!.value, 'iterate_prompt')
    },
    [promptInputRef, handleSubmit, handleIterationNavigation],
  )

  const fixAll = () => {
    if (errors.length === 0) return
    const attachments = getAttachments(errors)
    submitPrompt(fixAllPrompt, step, 'attachments', {attachments})

    attachAll(false)
    setDeployBuildErrors([])
  }

  const handleImageRemove = () => {
    clearImageAttachment()
    announce('Image removed')
    promptInputRef.current?.focus()
  }

  const selectIterationV2 = useCallback(
    async (refinement: Iteration) => {
      if (!fileSyncerStarted || syncerMode !== 'codespace') return
      const syncer = getFileSyncerV2()
      if (!syncer) return
      const sha = !refinement.branchName ? refinement.sha || '' : ''
      await syncer?.checkoutCommitish(sha, shouldForcePushToRemoteAfterCheckout, refinement.branchName)
      updateWorkbenchCurrentRefinement(refinement.id)
      await refreshGitHistory()
      forceContentRefresh()
      forceFileTreeRefresh()
    },
    [
      fileSyncerStarted,
      syncerMode,
      getFileSyncerV2,
      shouldForcePushToRemoteAfterCheckout,
      updateWorkbenchCurrentRefinement,
      refreshGitHistory,
      forceContentRefresh,
      forceFileTreeRefresh,
    ],
  )

  /*
   * If the FF is enabled, we will fetch the iteration history from git, which means that the id will be a string (sha)
   * If the FF is disabled, we will fetch the iteration history from the db, which means that it will be a number (auto-increment id)
   */
  const navigateToIteration = useCallback(
    async (refinement: Iteration) => {
      setIsNavigatingHistory(true)
      sendEvent('iteration_history.previous_iteration_selected', {
        refinementId: refinement.id!,
        workbenchId: workbenchData.id,
      })

      try {
        await selectIterationV2(refinement)
      } catch (error) {
        sendEvent('iteration_history.previous_iteration_selected_error', {
          ...(refinement.id != null && {refinementId: refinement.id}),
          ...(refinement.sha != null && {refinementSha: refinement.sha}),
          error: (error as Error).message,
        })
      } finally {
        setIsNavigatingHistory(false)
      }
    },
    [selectIterationV2, sendEvent, setIsNavigatingHistory, workbenchData.id],
  )

  const iterations = useMemo(() => {
    return previousRefinements.map(i => ({
      ...i,
      prompt: i.prompt?.includes(attachedErrorsPromptPrefix) ? i.prompt.split(attachedErrorsPromptPrefix)[0] : i.prompt,
    }))
  }, [previousRefinements])

  return (
    <div className={styles.container}>
      <Overscroll scrollingRef={scrollRef} />
      <div ref={scrollRef} className={styles.contentArea}>
        <ActivityLog
          previousRefinements={iterations.map(i => ({
            ...i,
            prompt: i.prompt?.includes(attachedErrorsPromptPrefix)
              ? i.prompt.split(attachedErrorsPromptPrefix)[0]
              : i.prompt,
          }))}
          onSelectRefinement={navigateToIteration}
          activeRefinement={activeRefinement!}
        />
      </div>
      {imageUploadError && (
        <Banner
          className={styles.alertBanner}
          ref={imageUploadErrorRef}
          variant="critical"
          title="Error attaching image"
          description={imageUploadError}
          hideTitle
          onDismiss={() => {
            attachImageButtonRef.current?.focus()
            setImageUploadError(undefined)
          }}
        />
      )}
      {promptError && (
        <Banner
          className={styles.alertBanner}
          variant="critical"
          title="Failed"
          description={promptError}
          hideTitle
          onDismiss={() => {
            promptInputRef.current?.focus()
            setPromptError(null)
          }}
        />
      )}
      {isCodespaceReady && (suggestions.length > 0 || errors.length > 0) && (
        <Suggestions
          suggestions={suggestions}
          errors={errors}
          onSelectSuggestion={suggestion =>
            handleSubmit(suggestion, 'suggestion', {suggestion_text: suggestion, rank: suggestions.indexOf(suggestion)})
          }
          attachAll={attachAll}
          fixAll={fixAll}
          isFetching={isFetching}
        />
      )}

      <form
        className={styles.formContainer}
        onSubmit={e => {
          e.preventDefault()
          if (readOnly) return
          handleSubmit(promptInputRef.current!.value, 'iterate_prompt')
        }}
      >
        <Textarea
          id="iterate-modal-input"
          ref={promptInputRef}
          className={styles.promptInputContainer}
          block
          rows={1}
          resize="none"
          placeholder={isFetching ? 'Copilot is working...' : 'What do you want to change?'}
          onChange={e => updatePromptText(e.target.value)}
          onKeyDown={handleKeyDown}
          onBlur={e => setGlobalPromptText(e.target.value)}
          disabled={readOnly || isFetching || !isCodespaceReady || !gitHistoryRestored}
        />
        <div className={styles.formContainerActions}>
          {promptImage && (
            <div role="toolbar" aria-label="Attachments" className={styles.attachmentToolbar}>
              <div className={styles.referenceToken}>
                <ImageIcon className="fgColor-muted" />
                <span className={styles.referenceTokenLabel}>{promptImage.name}</span>
                <IconButton
                  icon={XIcon}
                  variant="invisible"
                  size="small"
                  aria-label="Remove image"
                  onClick={handleImageRemove}
                />
              </div>
            </div>
          )}
          <div className="d-flex flex-items-center gap-1">
            {!promptImage && (
              <>
                <IconButton
                  variant="invisible"
                  icon={PaperclipIcon}
                  aria-label="Attach image"
                  ref={attachImageButtonRef}
                  onClick={() => imagesInputRef.current?.click()}
                  disabled={isFetching}
                />
                <input
                  id="image-uploader"
                  hidden
                  ref={imagesInputRef}
                  type="file"
                  accept={['image/jpeg', 'image/png', 'image/webp'].join(',')}
                  onChange={attachImage}
                />
              </>
            )}
            {isFetching ? (
              <IconButton
                className={styles.stopButton}
                aria-label="Stop current generation"
                icon={SquareFillIcon}
                variant="invisible"
                onClick={e => {
                  e.preventDefault()
                  e.stopPropagation()
                  cancelPrompt()
                }}
              />
            ) : (
              <IconButton
                aria-label={isCodespaceReady ? 'Send now' : 'Establishing connection…'}
                icon={PaperAirplaneIcon}
                variant="invisible"
                type="submit"
                inactive={!isCodespaceReady}
                disabled={readOnly}
              />
            )}
          </div>
        </div>
      </form>
    </div>
  )
}

export default IteratePanel

interface ActivityLogProps {
  previousRefinements: Iteration[]
  activeRefinement: Iteration
  onSelectRefinement: (v: Iteration) => void
}

const ActivityLog = ({activeRefinement, previousRefinements, onSelectRefinement}: ActivityLogProps) => {
  // Remove useMemo as React Compiler cannot preserve these memoizations
  const displayItems = buildDisplayRefinements(activeRefinement, previousRefinements)

  const lastItem = [...displayItems].reverse().find(item => item.type === 'refinement')?.refinement
  const lastRefinementId = lastItem?.sha

  return (
    <div className={styles.activityLogContainer}>
      {displayItems.map((item, i) => {
        if (item.type === 'refinement') {
          const {refinement} = item
          const isFirstRefinement = i === 0
          const isLastRefinement = lastRefinementId === refinement.sha

          return (
            <RefinementTimelineItem
              key={refinement.id}
              refinementIndex={i}
              refinement={refinement}
              isLastRefinement={isLastRefinement}
              isFirstRefinement={isFirstRefinement}
              onSelectRefinement={onSelectRefinement}
            />
          )
        }

        if (item.type === 'skip') {
          const skippedRefinements = item.skippedRefinements
          return (
            <div key={skippedRefinements[0]!.id} className={styles.skippedContainer}>
              <SkippedRefinementsTimelineItem
                skippedRefinements={skippedRefinements}
                onSelectRefinement={onSelectRefinement}
              />
            </div>
          )
        }
      })}
    </div>
  )
}

function isTextOverflowing(element: HTMLElement): boolean {
  return element.scrollWidth > element.clientWidth || element.scrollHeight > element.clientHeight
}

const RefinementTimelineItem = ({
  variant = 'default',
  refinementIndex,
  refinement,
  isLastRefinement,
  isFirstRefinement,
  onSelectRefinement,
}: {
  variant?: 'default' | 'skipped'
  refinementIndex: number
  refinement: Iteration
  isLastRefinement: boolean
  isFirstRefinement: boolean
  onSelectRefinement: (v: Iteration) => void
}) => {
  const {isFetching} = useWorkbenchContext()
  const {currentRefinementSha} = useIterationHistory()

  const [_showCollapseToggle, _setShowCollapseToggle] = useState(false)
  const [_promptCollapsed, _setPromptCollapsed] = useState(true)

  /**
   * hotfix for active refinement detection
   * while an iteration is in progress, always mark the last refinement as active
   * during loading we may not yet have a reliable SHA, so position is used as a fallback
   */
  const isActiveRefinement =
    isFetching && isLastRefinement ? true : refinement.sha != null && refinement.sha === currentRefinementSha

  // useEffect(() => {
  //   const label = document.querySelector(`[data-timeline-refinement-id="${refinement.id}"] .${styles.refinement}`)
  //   if (label && isTextOverflowing(label as HTMLElement)) {
  //     setShowCollapseToggle(true)
  //   } else {
  //     setShowCollapseToggle(false)
  //   }
  // }, [refinement.id])

  return (
    <div
      key={refinement.id || `generating-refinement`}
      data-timeline-refinement-id={refinement.id}
      data-timeline-refinement-active={isActiveRefinement}
      className={clsx(styles.timelineItem, 'ml-1', {
        [styles.lastTimelineItem]: isLastRefinement,
        [styles.firstTimelineItem]: isFirstRefinement,
      })}
    >
      <div className={styles.timelineBody}>
        {variant === 'skipped' ? (
          <SkippedRefinementEntry refinement={refinement} collapsed={false} />
        ) : (
          <ActiveRefinementEntry
            refinementIndex={refinementIndex}
            refinement={refinement}
            isActive={isActiveRefinement}
            isLastRefinement={isLastRefinement}
            onSelectRefinement={onSelectRefinement}
          />
        )}
      </div>
    </div>
  )
}

const RefinementLabel = ({
  refinement,
  // collapsed,
  // active,
}: {
  refinement: Iteration
  collapsed: boolean
  active?: boolean
}) => {
  const [_showCollapseToggle, _setShowCollapseToggle] = useState(false)
  const [promptCollapsed, setPromptCollapsed] = useState(true)

  const promptWithoutNewlines = useMemo(() => {
    // by default there are two new lines between markdown elements
    // which doesn't look well in collapsed state, because we want to show content
    // the result is:
    // # heading
    // ... <- new line truncated like this
    // instead we want:
    // # heading
    // some truncated text here...
    return refinement.prompt?.replaceAll('\n\n', '\n') ?? ''
  }, [refinement.prompt])

  const [textOverflowing, setTextOverflowing] = useState(false)
  const paragraphRef = useRef<HTMLParagraphElement>(null)
  useLayoutEffect(() => {
    if (paragraphRef.current) {
      setTextOverflowing(isTextOverflowing(paragraphRef.current))
    }
  }, [promptWithoutNewlines])

  switch (refinement.iteration_type) {
    case 'ai':
      return (
        <div className={styles.activityItemActive}>
          <div className={styles.actionsContainer}>
            {textOverflowing && (
              <IconButton
                variant="invisible"
                size="small"
                icon={promptCollapsed ? UnfoldIcon : FoldIcon}
                aria-label={promptCollapsed ? 'Expand prompt' : 'Collapse prompt'}
                onClick={() => {
                  setPromptCollapsed(c => !c)
                  announce(promptCollapsed ? 'Prompt expanded' : 'Prompt collapsed')
                }}
              />
            )}
            <CopyToClipboardButton
              variant="invisible"
              size="small"
              textToCopy={refinement.prompt ?? ''}
              ariaLabel="Copy prompt"
            />
            {/* {!isActiveRefinement && (
                <Button
                  size="small"
                  variant={isActiveRefinement ? 'invisible' : 'default'}
                  onClick={() => onSelectRefinement(refinement)}
                  disabled={canRestore === false}
                >
                  Restore
                </Button>
              )} */}
          </div>
          {promptCollapsed ? (
            <p
              ref={paragraphRef}
              data-fade={textOverflowing}
              className={styles.refinement}
              style={{
                '--lines-to-show': 5,
              }}
            >
              {promptWithoutNewlines}
            </p>
          ) : (
            <MarkdownRenderer
              markdown={refinement.prompt ?? ''}
              chatMode="assistive"
              className={styles.markdownContent}
            />
          )}
        </div>
      )
    case 'user':
      return <Label variant="secondary">Manual edit</Label>
    case 'from_repository':
      return <Label variant="secondary">Synced from repository</Label>
  }
}

const ActiveRefinementEntry = ({
  refinement,
  refinementIndex,
  isActive,
  isLastRefinement,
  onSelectRefinement,
}: {
  refinement: Iteration
  refinementIndex: number
  isActive: boolean
  isLastRefinement: boolean
  onSelectRefinement: (v: Iteration) => void
}) => {
  const [promptCollapsed, _setPromptCollapsed] = useState(true)

  const {isFetching} = useWorkbenchContext()
  const {isNavigatingHistory, gitHistoryRestored} = useIterationHistory()
  const {fileSyncerStarted, syncerMode} = useFileSyncerContext()
  const {latestAgentUpdate} = useServerEvents()

  // Agent activity should only show after intent summary completes or when there's an active update
  // Derive this state from the dependencies instead of using useEffect
  const hasActiveAgentUpdate = isFetching && Boolean(latestAgentUpdate && latestAgentUpdate.trim())
  const intentSummaryShown = Boolean(refinement.intentSummary)
  const hasHistoricalData =
    refinement.intentSummary &&
    (Object.keys(refinement.files).length > 0 ||
      (Array.isArray(refinement.completionSummary) && refinement.completionSummary.length > 0))

  const showAgentActivity = (hasActiveAgentUpdate && intentSummaryShown) || (hasHistoricalData && !isFetching)

  // Track if this refinement was actively worked on during this session (not just loaded from refresh)
  // Derive this state from the dependencies instead of using useEffect
  const wasActiveThisSession = isFetching && isLastRefinement

  const canRestore =
    fileSyncerStarted &&
    syncerMode === 'codespace' &&
    !isFetching &&
    !isNavigatingHistory &&
    !refinement.error &&
    gitHistoryRestored

  const handleIntentSummaryComplete = useCallback(() => {
    // Note: showAgentActivity is now computed, so this callback doesn't need to set state
    // The transition will happen automatically when the dependencies change
  }, [])

  // For the collapse toggle, we can compute this value instead of using useEffect
  // This is called when the component renders to check if text is overflowing
  const getShowCollapseToggle = useCallback(() => {
    const label = document.querySelector(`[data-timeline-refinement-id="${refinement.id}"] .${styles.refinement}`)
    return label && isTextOverflowing(label as HTMLElement)
  }, [refinement.id])

  const _showCollapseToggle = getShowCollapseToggle()

  return (
    <div className={clsx(styles.activityItem)}>
      <div className={styles.promptContainer}>
        <RefinementLabel refinement={refinement} collapsed={promptCollapsed} active />
      </div>
      {/* Intent Summary - with loading placeholder if needed */}
      <Summary
        content={refinement.intentSummary || ''}
        onAnimationComplete={handleIntentSummaryComplete}
        isLoading={isFetching && isLastRefinement && !refinement.intentSummary}
        loadingText="Copilot is thinking"
        shouldAnimate={isLastRefinement && isFetching}
      />
      {showAgentActivity && (
        <AgentActivity
          version={refinementIndex + 1}
          refinement={refinement}
          isActive={isActive}
          canRestore={canRestore}
          isLastRefinement={isLastRefinement}
          onRestore={() => onSelectRefinement(refinement)}
        />
      )}
      {/* Completion Summary - appears AFTER agent activity */}
      {(() => {
        const hasCompletionSummary =
          Array.isArray(refinement.completionSummary) && refinement.completionSummary.length > 0
        // Only animate if this refinement was active during this session and is now complete
        const shouldAnimateCompletion = wasActiveThisSession && !isFetching && hasCompletionSummary

        return (
          hasCompletionSummary &&
          refinement.completionSummary && (
            <Summary title="Summary" content={refinement.completionSummary} shouldAnimate={shouldAnimateCompletion} />
          )
        )
      })()}
    </div>
  )
}

const SkippedRefinementEntry = ({refinement, collapsed}: {refinement: Iteration; collapsed: boolean}) => {
  return (
    <div className={clsx(styles.activityItem, styles.activityItemSkipped)}>
      <div>
        <RefinementLabel refinement={refinement} collapsed={collapsed} />
      </div>
    </div>
  )
}

const SkippedRefinementsTimelineItem = ({
  skippedRefinements,
  onSelectRefinement,
}: {
  skippedRefinements: Iteration[]
  onSelectRefinement: (v: Iteration) => void
}) => {
  const [isExpanded, setIsExpanded] = useState<boolean>(false)

  const handleExpand = () => setIsExpanded(!isExpanded)

  return (
    <>
      <button
        onClick={() => handleExpand()}
        className={clsx(styles.buttonNaked, styles.skippedCaption)}
        aria-expanded={isExpanded}
      >
        <div className={styles.chevron} data-expanded={isExpanded}>
          <ChevronRightIcon size={12} />
        </div>
        <span className="text-small">
          {skippedRefinements.length === 1 ? '1 ignored version' : `${skippedRefinements.length} ignored versions`}
        </span>
      </button>
      {isExpanded && (
        <div className={styles.skippedContainer}>
          {skippedRefinements.map((refinement, i) => {
            return (
              <RefinementTimelineItem
                key={refinement.id}
                variant="skipped"
                refinementIndex={i}
                refinement={refinement}
                isFirstRefinement={false}
                isLastRefinement={false}
                onSelectRefinement={onSelectRefinement}
              />
            )
          })}
        </div>
      )}
    </>
  )
}

