import {
  ChevronRightIcon,
  CopilotIcon,
  DiffIcon,
  FileAddedIcon,
  FileCodeIcon,
  FileDiffIcon,
  FileRemovedIcon,
} from '@primer/octicons-react'
import {ActionList, BranchName, Button, Label} from '@primer/react'
import {clsx} from 'clsx'
import {useCallback, useEffect, useRef, useState} from 'react'

import {useEditorContext} from '../contexts/EditorContext'
import {useFileSyncerContext} from '../contexts/FileSyncerContext'
import {useIterationHistory} from '../contexts/IterationHistoryContext'
import {useServerEvents} from '../contexts/ServerEventsContext'
import {useWorkbenchContext} from '../contexts/WorkbenchContext'
import {useWorkbenchNavigate} from '../hooks/use-workbench-navigate'
import type {FileDescription} from '../types/spark-history-types'
import type {Iteration} from '../types/workbench-types'
import workbenchConsole from '../utilities/console'
import styles from './AgentActivity2.module.css'
import {Typewriter, WithShimmerEffect} from './shared/Typewriter'

interface AgentActivityProps {
  version: number
  refinement: Iteration
  isActive: boolean
  canRestore: boolean
  isLastRefinement: boolean
  onRestore: () => void
}

const SUPPORTED_FILE_EXTENSIONS = ['.md', '.tsx', '.html', '.ts', '.css']

const AgentActivity = ({
  version,
  refinement,
  isActive,
  isLastRefinement,
  canRestore,
  onRestore,
}: AgentActivityProps) => {
  const navigate = useWorkbenchNavigate()
  const {isFetching} = useWorkbenchContext()
  const {latestAgentUpdate} = useServerEvents()
  const {previousRefinementSha} = useIterationHistory()
  const {getFileSyncerV2, fileSyncerStarted} = useFileSyncerContext()
  const {setOriginalFileContent, editorMode, setDiffComputed, editorPath} = useEditorContext()

  const isLoading = isFetching && isLastRefinement
  const files = Object.values(refinement.files ?? {})

  const [isExpanded, setIsExpanded] = useState<boolean>(isActive)

  const [diffFileOpen, setDiffFileOpen] = useState<string | null>(null)
  const [hoveredFile, setHoveredFile] = useState<string | null>(null)
  const [focusedFile, setFocusedFile] = useState<string | null>(null)
  const itemRefs = useRef<Map<string, HTMLElement>>(new Map())
  const canDiff = Boolean(previousRefinementSha)

  useEffect(() => {
    setIsExpanded(isActive)
  }, [isActive])

  // Reset state when the path changes or when switching to editor mode
  useEffect(() => {
    if (editorMode === 'editor') {
      setDiffFileOpen(null)
      setOriginalFileContent(null)
    }
  }, [editorPath, editorMode, setDiffFileOpen, setOriginalFileContent])

  const handleMouseEnter = useCallback((e: React.MouseEvent<HTMLLIElement>, fileName: string) => {
    const itemRef = itemRefs.current.get(fileName)
    const currentTarget = e.currentTarget as Element
    if (itemRef && currentTarget && itemRef.contains(currentTarget)) {
      setHoveredFile(fileName)
    }
  }, [])

  const handleMouseLeave = useCallback(
    (e: React.MouseEvent<HTMLLIElement> | React.MouseEvent<HTMLButtonElement>, fileName: string) => {
      const itemRef = itemRefs.current.get(fileName)
      const relatedTarget = e.relatedTarget as Element
      if (!itemRef || !relatedTarget || !itemRef.contains(relatedTarget)) {
        setHoveredFile(null)
      }
    },
    [],
  )

  const handleBlur = useCallback(
    (e: React.FocusEvent<HTMLLIElement> | React.FocusEvent<HTMLButtonElement>, fileName: string) => {
      const itemRef = itemRefs.current.get(fileName)
      const relatedTarget = e.relatedTarget as Element
      if (!itemRef || !relatedTarget || !itemRef.contains(relatedTarget)) {
        setFocusedFile(null)
      }
    },
    [],
  )

  const handleItemRef = useCallback((fileName: string, element: HTMLElement | null) => {
    if (element?.parentElement) {
      // Reference <li> of ActionList.Item
      const liElement = element.closest('li')
      if (liElement) {
        itemRefs.current.set(fileName, liElement)
      }
    } else {
      itemRefs.current.delete(fileName)
    }
  }, [])

  const handleItemSelect = useCallback(
    (file: FileDescription) => {
      // Strip either /workspaces/spark/ or /workspaces/spark-template/
      const fmtFilePath = file.fileName.replace(/^\/workspaces\/spark(?:-template)?\//, '')
      navigate(fmtFilePath, {showCode: true})
      setDiffFileOpen(null)
    },
    [navigate],
  )

  const getPreviousFileContent = useCallback(
    async (filePath: string) => {
      const fileSyncer = getFileSyncerV2()
      if (!fileSyncer || !fileSyncerStarted || !previousRefinementSha) return
      try {
        const fileContent = await fileSyncer.getGitCatFile(previousRefinementSha, filePath)
        setOriginalFileContent(fileContent)
      } catch (error) {
        workbenchConsole.error(
          'Error retrieving previousRefinementSha file content:',
          previousRefinementSha,
          filePath,
          error,
        )
        setOriginalFileContent('')
      }
    },
    [fileSyncerStarted, getFileSyncerV2, previousRefinementSha, setOriginalFileContent],
  )

  const handleDiffClick = useCallback(
    async (file: FileDescription) => {
      if (!previousRefinementSha) return

      // If the diff file is already open, toggle it to file view
      const {fileName: filePath} = file
      if (diffFileOpen === filePath) {
        handleItemSelect(file)
        return
      }

      setDiffFileOpen(filePath)
      setOriginalFileContent(null) // Display loading skeleton for DiffEditor

      const fmtFilePath = filePath.replace(/^\/workspaces\/spark(?:-template)?\//, '')
      getPreviousFileContent(fmtFilePath)

      setDiffComputed(false)
      navigate(fmtFilePath, {editorMode: 'diff-editor', showCode: true})
    },
    [
      diffFileOpen,
      getPreviousFileContent,
      handleItemSelect,
      navigate,
      previousRefinementSha,
      setDiffComputed,
      setOriginalFileContent,
    ],
  )

  if (refinement.iteration_type === 'from_repository') {
    return null // Skip rendering for iterations from repository, they don't have the additional details
  }

  if (files.length === 0 && !isLoading) {
    return (
      <div className={clsx(styles.containerNoChanges, styles.fadeIn)}>
        No changes made
        <BranchName>v{refinement.id}</BranchName>
        <div className="ml-auto">
          {isActive ? (
            <Label variant="secondary">Current</Label>
          ) : (
            <Button size="small" variant="invisible" onClick={onRestore} disabled={!canRestore}>
              Restore
            </Button>
          )}
        </div>
      </div>
    )
  }

  return (
    <div className={clsx('border borderColor-muted rounded-3 bgColor-default', styles.fadeIn)}>
      <div className={styles.triggerContainer}>
        <button
          onClick={() => setIsExpanded(e => !e)}
          aria-expanded={isExpanded}
          className={clsx(styles.buttonNaked, styles.triggerButton, 'text-small', {'rounded-bottom-3': !isExpanded})}
        >
          <ChevronRightIcon size={16} data-expanded={isExpanded} className={styles.chevron} />
          {isLoading ? (
            <WithShimmerEffect>Generating</WithShimmerEffect>
          ) : (
            <span>{`Made ${files.length} change${files.length !== 1 ? 's' : ''}`}</span>
          )}
          <BranchName>v{version}</BranchName>
          {isActive && (
            <Label variant="secondary" className="ml-auto">
              Current
            </Label>
          )}
        </button>

        {!isActive && (
          <div className={styles.restoreButtonContainer}>
            <Button size="small" variant="invisible" onClick={onRestore} disabled={!canRestore}>
              Restore
            </Button>
          </div>
        )}
      </div>
      {isExpanded && (
        <>
          <div className="border-top borderColor-muted">
            {files.length > 0 && (
              <ActionList>
                {files.map(file => {
                  const canShowDiff =
                    canDiff &&
                    file.editType === 'update' &&
                    SUPPORTED_FILE_EXTENSIONS.some(extension => file.fileName.endsWith(extension))

                  const showDiff =
                    canShowDiff &&
                    (hoveredFile === file.fileName || focusedFile === file.fileName || diffFileOpen === file.fileName)

                  return (
                    <ActionList.Item
                      key={file.fileName}
                      ref={(el: HTMLElement | null) => {
                        handleItemRef(file.fileName, el)
                      }}
                      onSelect={() => handleItemSelect(file)}
                      onMouseEnter={e => handleMouseEnter(e, file.fileName)}
                      onMouseLeave={e => handleMouseLeave(e, file.fileName)}
                      onFocus={() => setFocusedFile(file.fileName)}
                      onBlur={e => handleBlur(e, file.fileName)}
                      aria-label={`Open ${shortenFileName(file.fileName)}`}
                      aria-labelledby={undefined} // Unsets aria-labelledby to fix competing aria-label and aria-labelledby warning
                    >
                      <div className="d-flex flex-row gap-2 flex-items-center py-0">
                        {getFileIcon(file.editType)}
                        <div>{shortenFileName(file.fileName)}</div>
                      </div>
                      {showDiff && (
                        <ActionList.TrailingAction
                          className={clsx(styles.diffButton, diffFileOpen === file.fileName && styles.diffButtonActive)}
                          label="View diff"
                          icon={DiffIcon}
                          onClick={() => handleDiffClick(file)}
                          onMouseLeave={(e: React.MouseEvent<HTMLButtonElement>) => handleMouseLeave(e, file.fileName)}
                          onBlur={(e: React.FocusEvent<HTMLButtonElement>) => handleBlur(e, file.fileName)}
                        />
                      )}
                    </ActionList.Item>
                  )
                })}
              </ActionList>
            )}
          </div>
          {isLoading && (
            <div className={clsx(styles.agentMessageContainer, {'mt-3': files.length === 0})}>
              <CopilotIcon className={styles.copilotIcon} />
              <Typewriter text={filterDoneStatement(latestAgentUpdate || 'Copilot is thinking')} speed={30} />
            </div>
          )}
        </>
      )}
    </div>
  )
}

const filterDoneStatement = (text: string): string => {
  // Remove "DONE." only if it appears at the end of the text
  return text.replace(/\s*DONE\.?\s*$/, '').trim()
}

const shortenFileName = (fileName?: string): string => {
  if (!fileName) return ''
  const lastSlashIndex = fileName.lastIndexOf('/')
  return lastSlashIndex !== -1 ? fileName.slice(lastSlashIndex + 1) : fileName
}

const getFileIcon = (editType: string | undefined) => {
  switch (editType) {
    case 'create':
      return <FileAddedIcon className="fgColor-success" />
    case 'update':
      return <FileDiffIcon className="fgColor-muted" />
    case 'delete':
      return <FileRemovedIcon className="fgColor-danger" />
    default:
      return <FileCodeIcon className="fgColor-muted" />
  }
}

export default AgentActivity

try{ AgentActivity.displayName ||= 'AgentActivity' } catch {}